-- Version 010: A-To-Do's interface texts move into the maleniti schema's
-- translations (migration 004), so a language can be added and its texts
-- edited from the admin app, without a client release.
--
-- A named translation key is one interface text of a brand's client:
--
--   brand_id  the brand whose client shows it (A-To-Do)
--   bundle    which part of the client loads it -- 'app' (the to-do app),
--             'common' (every page), or one marketing/legal page each
--             ('landing', 'checkout', 'success', 'cancel', 'privacy',
--             'terms', 'faq', 'support')
--   name      the key the client looks it up by ('todo.addTask'), unique
--             within the brand (a page loads several bundles together)
--
-- The texts that back business data (price lists' product names...) stay
-- unnamed. The client fetches a language's texts per bundle from
-- GET /atodo/v1/translations, the languages from GET /atodo/v1/languages.
--
-- A deleted language takes its translations with it, and an account that
-- used it goes back to choosing (the API refuses deleting English, the
-- fallback for a missing text, and Croatian, the price lists' language).
-- An account's language is now any language there is, not just en/hr.
--
-- Seeded with every text the client had (English and Croatian), the
-- activity log's entries (written in English by the API, shown in the
-- user's language -- lib/atodo/domain/logEntries.js) and the landing
-- page's walkthrough video links (one per language; an empty one shows a
-- placeholder).

ALTER TABLE maleniti.translation_key
    ADD COLUMN brand_id INT REFERENCES maleniti.brand,
    ADD COLUMN bundle TEXT,
    ADD COLUMN name TEXT,
    ADD CONSTRAINT translation_key_named CHECK (num_nulls(brand_id, bundle, name) IN (0, 3));

CREATE UNIQUE INDEX translation_key_name ON maleniti.translation_key (brand_id, name) WHERE name IS NOT NULL;

ALTER TABLE maleniti.translation
    DROP CONSTRAINT translation_language_id_fkey,
    ADD CONSTRAINT translation_language_id_fkey FOREIGN KEY (language_id) REFERENCES maleniti.language ON DELETE CASCADE;

ALTER TABLE atodo.accounts
    DROP CONSTRAINT accounts_language_check,
    ADD CONSTRAINT accounts_language_fkey FOREIGN KEY (language) REFERENCES maleniti.language ON DELETE SET NULL;

-- One A-To-Do interface text in English and Croatian; only for this script.
CREATE FUNCTION pg_temp.ui(bundle TEXT, name TEXT, en TEXT, hr TEXT) RETURNS VOID LANGUAGE plpgsql AS $$
DECLARE
    new_trid INT;
BEGIN
    INSERT INTO maleniti.translation_key (brand_id, bundle, name)
    SELECT brand_id, ui.bundle, ui.name FROM maleniti.brand WHERE code = 'atodo'
    RETURNING trid INTO new_trid;
    INSERT INTO maleniti.translation (trid, language_id, text) VALUES
        (new_trid, 'en', en),
        (new_trid, 'hr', hr);
END;
$$;

