SELECT pg_temp.ui('support', 'support.hint.billing', 'Tell us what happened and when - e.g. a payment you don''t recognise, a charge you didn''t expect, or a refund you''d like.', 'Opišite što se i kada dogodilo - npr. plaćanje koje ne prepoznajete, neočekivana naplata ili povrat novca koji želite.');
SELECT pg_temp.ui('support', 'support.hint.account', 'If you can''t log in, use the email address of the account - we''ll reply to the address you enter above.', 'Ako se ne možete prijaviti, upišite e-mail adresu računa - odgovorit ćemo na adresu koju upišete gore.');
SELECT pg_temp.ui('support', 'support.hint.bug', 'What did you do, what did you expect, and what happened instead? Which device and browser? Screenshots help - we''ll ask for them by email.', 'Što ste napravili, što ste očekivali i što se dogodilo umjesto toga? Koji uređaj i preglednik? Snimke zaslona pomažu - zatražit ćemo ih e-mailom.');
SELECT pg_temp.ui('support', 'support.hint.feature', 'What would you like A-To-Do to do, and what would it help you with?', 'Što biste voljeli da A-To-Do radi i u čemu bi vam to pomoglo?');
SELECT pg_temp.ui('support', 'support.hint.complaint', 'Describe what you are complaining about. We confirm every complaint and answer it in writing within 15 days.', 'Opišite na što se prigovor odnosi. Svaki prigovor potvrđujemo i na njega pisano odgovaramo u roku od 15 dana.');
SELECT pg_temp.ui('support', 'support.hint.other', '', '');
SELECT pg_temp.ui('support', 'support.consent', 'I agree that A-To-Do may use the details in this form to reply to my message. Details in the <a href="privacy.html">Privacy Policy</a>.', 'Slažem se da A-To-Do upotrijebi podatke iz ovog obrasca kako bi odgovorio na moju poruku. Detalji u <a href="privacy.html">Pravilima privatnosti</a>.');
SELECT pg_temp.ui('support', 'support.replyTime', 'We''ll reply by email as soon as we can.', 'Odgovorit ćemo e-mailom što je prije moguće.');
SELECT pg_temp.ui('support', 'support.send', 'Send', 'Pošalji');
SELECT pg_temp.ui('support', 'support.sending', 'Sending…', 'Šalje se…');
SELECT pg_temp.ui('support', 'support.sent', 'Thanks - your message has been sent. We''ll reply by email.', 'Hvala - vaša je poruka poslana. Odgovorit ćemo e-mailom.');
SELECT pg_temp.ui('support', 'support.failed', 'Your message couldn''t be sent. Please try again in a moment.', 'Poruku nije bilo moguće poslati. Pokušajte ponovno za trenutak.');
